        "description": "ਗਚੀਬੋਵਲੀ ਜੰਕਸ਼ਨ ਦੇ ਨੇੜੇ ਸੜਕ ਚੌੜੀ ਕਰਨ ਦਾ ਕੰਮ ਅੱਧ ਵਿਚਕਾਰ ਹੀ ਛੱਡ ਦਿੱਤਾ ਗਿਆ ਹੈ। ਸੜਕ 'ਤੇ ਲਗਾਏ ਗਏ ਬੈਰੀਕੇਡਾਂ ਕਾਰਨ ਰੋਜ਼ਾਨਾ ਭੀੜ ਵਾਲੇ ਘੰਟਿਆਂ ਦੌਰਾਨ ਭਾਰੀ ਟ੍ਰੈਫਿਕ ਜਾਮ ਲੱਗਦਾ ਹੈ। GHMC ਅਤੇ NHAI ਨੂੰ ਕਈ ਸ਼ਿਕਾਇਤਾਂ ਕੀਤੀਆਂ ਗਈਆਂ ਹਨ, ਪਰ ਕੋਈ ਜਵਾਬ ਨਹੀਂ ਮਿਲਿਆ।"
